      '{\n  "name": "samebase-base",\n  "version": "0.0.0",\n  "private": true,\n  "license": "Apache-2.0",\n  "type": "module",\n  "imports": {\n    "#components/*": "./src/components/*.tsx",\n    "#lib/*": "./src/lib/*.ts",\n    "#hooks/*": "./src/hooks/*.ts"\n  },\n  "scripts": {\n    "dev": "node ./scripts/run-context-dev.ts",\n    "dev:primary": "node ./scripts/run-primary-dev.ts",\n    "dev:frontend": "vp dev",\n    "dev:worktree": "node ./scripts/run-worktree-dev.ts",\n    "check": "vp check && vp run typecheck && vp test",\n    "build": "vp run check && vp build",\n    "deploy": "convex-hosting deploy --build \\"vp run build && node ./scripts/ensure-convex-auth.ts --prod\\" --dist dist/client --html-handling drop-trailing-slash",\n    "deploy:dev": "convex-hosting deploy --dev --build \\"vp run build && node ./scripts/ensure-convex-auth.ts\\" --dist dist/client --html-handling drop-trailing-slash",\n    "format": "vp fmt",\n    "format:check": "vp fmt --check",\n    "lint": "vp lint --report-unused-disable-directives",\n    "preview": "vp preview",\n    "prepare": "vp config --no-agent",\n    "test": "vp test",\n    "typecheck": "tsc && vp run typecheck:node && tsc --project convex/tsconfig.json",\n    "typecheck:node": "tsc --project tsconfig.node.json"\n  },\n  "dependencies": {\n    "@convex-dev/auth": "2.0.0-beta.0",\n    "@convex-dev/react-query": "^0.1.0",\n    "@fontsource/google-sans": "^5.3.2",\n    "@samebase/convex-auth-tanstack-start": "^0.1.1",\n    "@samebase/convex-hosting": "^0.14.0",\n    "@samebase/convex-hosting-tanstack-start": "^0.11.0",\n    "@tailwindcss/vite": "^4.3.3",\n    "@tanstack/react-query": "^5.105.0",\n    "@tanstack/react-router": "^1.170.46",\n    "@tanstack/react-router-ssr-query": "1.167.3",\n    "@tanstack/react-start": "^1.169.4",\n    "class-variance-authority": "^0.7.1",\n    "clsx": "^2.1.1",\n    "convex": "^1.48.0",\n    "lucide-react": "^1.64.0",\n    "qrcode.react": "^4.2.0",\n    "radix-ui": "^1.8.1",\n    "react": "^19.3.1",\n    "react-dom": "^19.3.1",\n    "tailwind-merge": "^3.7.0",\n    "tailwindcss": "^4.3.3",\n    "tw-animate-css": "^1.4.0"\n  },\n  "devDependencies": {\n    "@alchemy.run/github": "2.0.0-beta.84",\n    "@effect/platform-node": "4.0.5",\n    "@samebase/alchemy-convex": "0.20.0",\n    "@tanstack/router-plugin": "^1.168.48",\n    "@types/node": "^26.6.6",\n    "@types/react": "^19.3.0",\n    "@types/react-dom": "^19.3.0",\n    "@vitejs/plugin-react": "^6.1.2",\n    "alchemy": "2.0.0-beta.84",\n    "effect": "4.0.5",\n    "shadcn": "4.22.1",\n    "typescript": "7.0.2",\n    "vite": "catalog:",\n    "vite-plus": "catalog:",\n    "vitest": "catalog:"\n  },\n  "packageManager": "pnpm@12.15.0"\n}\n',
