      'import { ConvexQueryClient } from "@convex-dev/react-query";\nimport { QueryClient } from "@tanstack/react-query";\nimport { createRouter as createTanStackRouter } from "@tanstack/react-router";\nimport { setupRouterSsrQueryIntegration } from "@tanstack/react-router-ssr-query";\nimport { routeTree } from "./routeTree.gen";\n\nexport function getRouter() {\n  const convexUrl = import.meta.env["VITE_CONVEX_URL"];\n  if (!convexUrl) {\n    throw new Error("VITE_CONVEX_URL is required. Run a supported Samebase dev or deploy command.");\n  }\n\n  // The server calls this for each request, so requests never share a client.\n  const convexQueryClient = new ConvexQueryClient(convexUrl, {\n    // Holds queries until the session is known; `SessionProvider` releases it without one.\n    expectAuth: true,\n  });\n  const queryClient = new QueryClient({\n    defaultOptions: {\n      queries: {\n        queryKeyHashFn: convexQueryClient.hashFn(),\n        queryFn: convexQueryClient.queryFn(),\n      },\n    },\n  });\n  convexQueryClient.connect(queryClient);\n\n  const router = createTanStackRouter({\n    routeTree,\n    context: { queryClient, convexQueryClient },\n    defaultPreload: "intent",\n    scrollRestoration: true,\n  });\n  setupRouterSsrQueryIntegration({ router, queryClient });\n\n  return router;\n}\n\ndeclare module "@tanstack/react-router" {\n  interface Register {\n    router: ReturnType<typeof getRouter>;\n  }\n}\n',
    "src/routes/__root.tsx":
      'import type { ConvexQueryClient } from "@convex-dev/react-query";\nimport { SessionProvider, SignedIn, sessionBeforeLoad } from "@samebase/convex-auth-tanstack-start";\nimport type { QueryClient } from "@tanstack/react-query";\nimport {\n  HeadContent,\n  Link,\n  Outlet,\n  Scripts,\n  createRootRouteWithContext,\n} from "@tanstack/react-router";\nimport type { ReactNode } from "react";\nimport appCss from "../style.css?url";\nimport { Button } from "#components/ui/button";\n\nexport const Route = createRootRouteWithContext<{\n  queryClient: QueryClient;\n  convexQueryClient: ConvexQueryClient;\n}>()({\n  beforeLoad: sessionBeforeLoad,\n  head: () => ({\n    meta: [\n      {\n        charSet: "utf-8",\n      },\n      {\n        name: "viewport",\n        content: "width=device-width, initial-scale=1",\n      },\n      {\n        title: "Samebase app",\n      },\n    ],\n    links: [\n      {\n        rel: "icon",\n        type: "image/svg+xml",\n        href: "/favicon.svg",\n      },\n      {\n        rel: "stylesheet",\n        href: appCss,\n      },\n    ],\n  }),\n  component: RootComponent,\n  notFoundComponent: NotFoundPage,\n});\n\nfunction RootComponent() {\n  const { convexQueryClient, token } = Route.useRouteContext();\n  return (\n    <SessionProvider client={convexQueryClient.convexClient} token={token}>\n      <RootDocument>\n        <nav className="mx-auto flex w-full max-w-2xl pt-2">\n          <Button asChild variant="link">\n            <Link to="/" activeOptions={{ exact: true }}>\n              Home\n            </Link>\n          </Button>\n          <Button asChild variant="link">\n            <Link to="/about">About</Link>\n          </Button>\n          {/* The server renders as the session of the request\'s cookies, so the first HTML already\n              has the right link. A prerendered page fills it in once the browser knows. */}\n          <SignedIn>\n            <Button asChild variant="link">\n              <Link to="/account">Account</Link>\n            </Button>\n          </SignedIn>\n        </nav>\n        <Outlet />\n      </RootDocument>\n    </SessionProvider>\n  );\n}\n\nfunction RootDocument({ children }: Readonly<{ children: ReactNode }>) {\n  return (\n    <html lang="en">\n      <head>\n        <HeadContent />\n      </head>\n      <body>\n        {children}\n        <Scripts />\n      </body>\n    </html>\n  );\n}\n\nfunction NotFoundPage() {\n  return <p>Not Found</p>;\n}\n',
